  ('peanut', '/ˈpiː.nʌt/', '花生', 'A small, edible seed often used in snacks and cooking.'),
  ('compelling', '/kəmˈpɛl.ɪŋ/', '引人注目的；令人信服的', 'Evoking interest, attention, or admiration in a powerful way.'),
